-- 离线算的最小开拉代价（巡逻路径全程推演），运行时只读这张表。
CREATE TABLE IF NOT EXISTS `ai_playerbot_pull_timing` (
  `map` smallint unsigned NOT NULL,
  `ord` smallint unsigned NOT NULL,
  `best_cost` smallint unsigned NOT NULL DEFAULT 0,
  `best_phase_ms` int unsigned NOT NULL DEFAULT 0,
  `cycle_ms` int unsigned NOT NULL DEFAULT 0,
  `calc_at` datetime NOT NULL,
  `source` varchar(32) NOT NULL DEFAULT 'offline-path',
  PRIMARY KEY (`map`,`ord`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `ai_playerbot_pull_timing` WHERE `map` IN (540,542,543,545,546,547,552,553,555,556,557,558);

